// gemm, s2s: two levels of Strassen on one shared array (own code; generated by tasks/gemm/reference/gen_strassen.py).
//
// T = E: a weight tile is E x E. The memory holds, at scale q = log2(N / E), the 7^m weight combinations of
// m = min(q, 2) Strassen levels at 18 bits (the declared layout); a tile is one burst: E beats of low 16 bits,
// then the upper bits. Per job, in chunks of at most 8 E vectors split in 4 column parts: the chunk's
// activations are written to the on-chip buffer, one bank per activation block; then, row block by row block, for
// every product and every column block the tile is loaded into the cells' shadow registers while the previous tile
// computes, the product's activation operand (a signed sum of up to 4 blocks) streams through the array, the
// row sums are added with the product's signs into the accumulators of its result blocks, and after the row
// block's last product the result blocks are read out through the output stage into the result FIFO.
module gemm #(parameter int LGE = 2, parameter int LAT = 3) (
  input  logic                   clk, rst,
  input  logic                   job_valid,
  input  logic [3:0]             job_lgn,
  input  logic [15:0]            job_batch, job_mul,
  input  logic [5:0]             job_shift,
  input  logic [15:0]            job_zp, job_lo, job_hi,
  input  logic                   rq_ready,
  input  logic                   rd_valid,
  input  logic [16*(1<<LGE)-1:0] rd_data,
  input  logic                   x_valid,
  input  logic [16*(1<<LGE)-1:0] x_data,
  input  logic                   y_ready,
  output logic                   job_ready,
  output logic                   rq_valid,
  output logic [31:0]            rq_addr,
  output logic [23:0]            rq_len,
  output logic                   rd_ready,
  output logic                   x_ready,
  output logic                   y_valid,
  output logic [15:0]            y_vec,
  output logic [4:0]             y_row,
  output logic [16*(1<<LGE)-1:0] y_data
);
  localparam int E = 1 << LGE;
  localparam int MEMW = 16 * E;
  localparam int KW = LGE + 1;                    // a vector index inside a column part (2 E vectors)
  localparam int CBW = 5 - 2;                      // a column block inside a row part
  localparam int AW = KW + CBW;                      // an address inside a buffer bank
  localparam int LGS = (AW > 10) ? AW - 10 : 0;
  localparam int VW = LGE + 1 + 2;              // a vector index inside a chunk (8 E vectors)
  localparam int DL = E + 2;                         // from a buffer read to row 0's accumulator read
  localparam int DRAIN = 2 * E + 4;                  // from a block's last buffer read to its read-out
  localparam int CAP = 16;                           // result beats under way at most (the FIFO's size)
  localparam int LGUB = (LGE + 2 > 5) ? LGE + 2 - 5 : 0;   // log2 of a tile's beats of upper bits
  localparam int HW = (LGUB > 0) ? LGUB : 1;
  localparam int TBEATS = E + (1 << LGUB);           // beats of a tile
  localparam int ACW = KW + 45;                    // the accumulate control of a row
  localparam int CW = KW + 6 + 2;               // the same, compact: valid, first column block, product, vector

  // ---- the job
  logic [1:0]  mode;                                 // Strassen levels in use: min(log2(N / E), 2)
  logic [2:0]  lgh;                                  // log2 of the column blocks of a row part
  logic [CBW-1:0] hbm;                               // column blocks of a row part - 1
  logic [4:0]  nbm;                                  // N / E - 1
  logic [2-1:0] nrm;                               // row parts - 1
  logic [6-1:0] npm;                            // products - 1
  logic [15:0] rem, vbase;
  logic [15:0] mul, zp, lo, hi;
  logic [5:0]  shift;
  logic [VW:0] cnt;                                  // vectors in this chunk, 1 .. 8 E
  logic [KW:0] part;                                 // vectors of a column part, ceil(cnt / 4)

  // ---- the main sequence
  typedef enum logic [2:0] {M_IDLE, M_CHUNK, M_INGEST, M_TILE, M_RUN, M_DRAIN, M_RO, M_FLUSH} mstate_t;
  mstate_t     ms;
  logic [VW:0] iv;                                   // ingest: vector of the chunk
  logic [KW-1:0] ik;                                 // ingest: vector of the column part
  logic [2-1:0] ica, ia;                           // ingest: column part, row part
  logic [4:0]  ic;                                   // ingest: beat of the vector
  logic [CBW-1:0] icb;                               // ingest: beat of the row part
  logic [CBW-1:0] rr, cc;                            // the tile: row block, column block
  logic [6-1:0] pp;                             // the product
  logic [KW:0] rv;                                   // the vector being read
  logic [15:0] dcnt;                                 // drain counter
  logic [2-1:0] ro_rho, ro_ch;                     // read-out: row part, column part
  logic [VW:0] ro_vb;                                // read-out: first vector of the column part

  // ---- registers that drive the children
  logic            swap;
  logic            xb_rd;
  logic [AW-1:0]   xb_ra;
  logic [6-1:0] xb_pid;                         // the product whose operand is being read
  logic [E-1:0]    ld;
  logic [(1<<HW)-1:0] ld_hi;
  logic [MEMW-1:0] wbeat;
  logic [(DL-1)*CW-1:0] actl;                        // the accumulate control on its way to row 0, compact
  logic [ACW-1:0]  acw;                              // decoded, at row 0
  logic            r_rd;
  logic [4-1:0] r_g;
  logic [2-1:0] r_sub;
  logic [KW-1:0]   r_v;
  logic [20:0]     r_tag;                            // the position (vector, row block) of the beat being read out
  logic [6-1:0] t_valid;                          // read-out pipeline: valid, and the beat's position
  logic [6*21-1:0] t_tag;
  logic [4:0]      occ;                              // result beats issued and not yet transferred

  // ---- the weight loader
  typedef enum logic [1:0] {L_IDLE, L_REQ, L_RX} lstate_t;
  lstate_t     ls;
  logic [12:0] tiles;                                // tiles of this chunk not yet requested
  logic [6-1:0] lp;
  logic [CBW-1:0] lr, lc;
  logic [LGE:0] li;
  logic        sh_full;
  logic [15:0] wave;                                 // cycles until the last swap has passed every cell

  logic [MEMW*(16<<LGS)-1:0] xq;
  logic [6-1:0] xqpid;
  logic [LGS:0]    xqsb;
  logic [E-1:0]    sk_swap;
  logic [19*E-1:0] sk_x;
  logic [MEMW-1:0] ya;
  logic            f_valid;
  logic [MEMW+20:0] f_dout;

  gemm_xbuf #(.LGE(LGE)) xbuf (
    .clk(clk), .we_v(x_valid), .we_r(x_ready), .wblk({ia, ica}), .waddr({ik, icb}), .wdata(x_data),
    .rd(xb_rd), .rmode(mode), .rpid(xb_pid), .raddr(xb_ra),
    .q(xq), .qpid(xqpid), .qsb(xqsb));
  gemm_skew #(.LGE(LGE)) skew (
    .clk(clk), .swap(swap), .q(xq), .mode(mode), .qpid(xqpid), .qsb(xqsb),
    .swap_o(sk_swap), .x_o(sk_x));
  gemm_array #(.LGE(LGE)) array (
    .clk(clk), .ld(ld), .ld_hi(ld_hi), .w_d(wbeat), .swap(sk_swap), .x(sk_x), .acw(acw),
    .r_rd(r_rd), .r_g(r_g), .r_sub(r_sub), .r_v(r_v), .mul(mul), .shift(shift), .zp(zp), .lo(lo), .hi(hi), .y(ya));
  gemm_fifo #(.W(MEMW + 21), .LGD(4)) fifo (
    .clk(clk), .rst(rst), .push(t_valid[6-1]), .din({t_tag[(6-1)*21 +: 21], ya}), .pop_ready(y_ready),
    .valid(f_valid), .dout(f_dout));
  assign y_valid = f_valid;
  assign y_data  = f_dout[MEMW-1:0];
  assign y_row   = f_dout[MEMW +: 5];
  assign y_vec   = f_dout[MEMW+5 +: 16];

  // ---- the product tables (constants of the algorithm): by {mode, product}; the operands' table is in the
  // buffer and in the skew, which get the product's number
  logic [45-1:0]  ptt;                             // the targets: per group {slot, first, negate, enable}
  logic [6-1:0] pseg;                           // the loader's product: its weight segment
  logic [4+2-1:0] ygs;                         // read-out: the block's {group, slot}
  logic [6-1:0] a_pid;
  assign a_pid = actl[(DL-1)*CW-3 -: 6];
  always_comb begin
    case ({mode, a_pid})
      8'd0: ptt = 45'h500000;
      8'd1: ptt = 45'ha000000;
      8'd2: ptt = 45'h2800000000;
      8'd3: ptt = 45'h50000000000;
      8'd64: ptt = 45'h528000;
      8'd65: ptt = 45'h1a018000;
      8'd66: ptt = 45'ha008000;
      8'd67: ptt = 45'h12100000;
      8'd68: ptt = 45'h2300000;
      8'd69: ptt = 45'h8000;
      8'd70: ptt = 45'h100000;
      8'd71: ptt = 45'h2940000000;
      8'd72: ptt = 45'hd00c0000000;
      8'd73: ptt = 45'h50040000000;
      8'd74: ptt = 45'h90800000000;
      8'd75: ptt = 45'h11800000000;
      8'd76: ptt = 45'h40000000;
      8'd77: ptt = 45'h800000000;
      8'd128: ptt = 45'h5280a5;
      8'd129: ptt = 45'h1a01b403;
      8'd130: ptt = 45'ha009401;
      8'd131: ptt = 45'h12102420;
      8'd132: ptt = 45'h2300460;
      8'd133: ptt = 45'h8001;
      8'd134: ptt = 45'h100020;
      8'd135: ptt = 45'h6b40000063;
      8'd136: ptt = 45'h1d02c0002c01;
      8'd137: ptt = 45'h150240000c03;
      8'd138: ptt = 45'h194800002c60;
      8'd139: ptt = 45'h115800000c20;
      8'd140: ptt = 45'h240000003;
      8'd141: ptt = 45'h4800000060;
      8'd142: ptt = 45'h2940000021;
      8'd143: ptt = 45'hd00c0002403;
      8'd144: ptt = 45'h50040000401;
      8'd145: ptt = 45'h90800002420;
      8'd146: ptt = 45'h11800000460;
      8'd147: ptt = 45'h40000001;
      8'd148: ptt = 45'h800000020;
      8'd149: ptt = 45'h4a40108000;
      8'd150: ptt = 45'h1902d2018000;
      8'd151: ptt = 45'h110242008000;
      8'd152: ptt = 45'h194812100000;
      8'd153: ptt = 45'h115802300000;
      8'd154: ptt = 45'h240008000;
      8'd155: ptt = 45'h4800100000;
      8'd156: ptt = 45'h840318000;
      8'd157: ptt = 45'h900d6008000;
      8'd158: ptt = 45'h10046018000;
      8'd159: ptt = 45'h90816300000;
      8'd160: ptt = 45'h11806100000;
      8'd161: ptt = 45'h40018000;
      8'd162: ptt = 45'h800300000;
      8'd163: ptt = 45'h21;
      8'd164: ptt = 45'h2403;
      8'd165: ptt = 45'h401;
      8'd166: ptt = 45'h2420;
      8'd167: ptt = 45'h460;
      8'd168: ptt = 45'h1;
      8'd169: ptt = 45'h20;
      8'd170: ptt = 45'h108000;
      8'd171: ptt = 45'h12018000;
      8'd172: ptt = 45'h2008000;
      8'd173: ptt = 45'h12100000;
      8'd174: ptt = 45'h2300000;
      8'd175: ptt = 45'h8000;
      8'd176: ptt = 45'h100000;
      default: ptt = '0;
    endcase
  end
  always_comb begin
    case ({mode, lp})
      8'd0: pseg = 6'd0;
      8'd1: pseg = 6'd0;
      8'd2: pseg = 6'd0;
      8'd3: pseg = 6'd0;
      8'd64: pseg = 6'd0;
      8'd65: pseg = 6'd1;
      8'd66: pseg = 6'd2;
      8'd67: pseg = 6'd3;
      8'd68: pseg = 6'd4;
      8'd69: pseg = 6'd5;
      8'd70: pseg = 6'd6;
      8'd71: pseg = 6'd0;
      8'd72: pseg = 6'd1;
      8'd73: pseg = 6'd2;
      8'd74: pseg = 6'd3;
      8'd75: pseg = 6'd4;
      8'd76: pseg = 6'd5;
      8'd77: pseg = 6'd6;
      8'd128: pseg = 6'd0;
      8'd129: pseg = 6'd1;
      8'd130: pseg = 6'd2;
      8'd131: pseg = 6'd3;
      8'd132: pseg = 6'd4;
      8'd133: pseg = 6'd5;
      8'd134: pseg = 6'd6;
      8'd135: pseg = 6'd7;
      8'd136: pseg = 6'd8;
      8'd137: pseg = 6'd9;
      8'd138: pseg = 6'd10;
      8'd139: pseg = 6'd11;
      8'd140: pseg = 6'd12;
      8'd141: pseg = 6'd13;
      8'd142: pseg = 6'd14;
      8'd143: pseg = 6'd15;
      8'd144: pseg = 6'd16;
      8'd145: pseg = 6'd17;
      8'd146: pseg = 6'd18;
      8'd147: pseg = 6'd19;
      8'd148: pseg = 6'd20;
      8'd149: pseg = 6'd21;
      8'd150: pseg = 6'd22;
      8'd151: pseg = 6'd23;
      8'd152: pseg = 6'd24;
      8'd153: pseg = 6'd25;
      8'd154: pseg = 6'd26;
      8'd155: pseg = 6'd27;
      8'd156: pseg = 6'd28;
      8'd157: pseg = 6'd29;
      8'd158: pseg = 6'd30;
      8'd159: pseg = 6'd31;
      8'd160: pseg = 6'd32;
      8'd161: pseg = 6'd33;
      8'd162: pseg = 6'd34;
      8'd163: pseg = 6'd35;
      8'd164: pseg = 6'd36;
      8'd165: pseg = 6'd37;
      8'd166: pseg = 6'd38;
      8'd167: pseg = 6'd39;
      8'd168: pseg = 6'd40;
      8'd169: pseg = 6'd41;
      8'd170: pseg = 6'd42;
      8'd171: pseg = 6'd43;
      8'd172: pseg = 6'd44;
      8'd173: pseg = 6'd45;
      8'd174: pseg = 6'd46;
      8'd175: pseg = 6'd47;
      8'd176: pseg = 6'd48;
      default: pseg = '0;
    endcase
  end
  always_comb begin
    case ({ro_rho, ro_ch})
      4'd0: ygs = 6'd16;
      4'd1: ygs = 6'd20;
      4'd2: ygs = 6'd28;
      4'd3: ygs = 6'd32;
      4'd4: ygs = 6'd21;
      4'd5: ygs = 6'd12;
      4'd6: ygs = 6'd33;
      4'd7: ygs = 6'd24;
      4'd8: ygs = 6'd29;
      4'd9: ygs = 6'd34;
      4'd10: ygs = 6'd4;
      4'd11: ygs = 6'd8;
      4'd12: ygs = 6'd35;
      4'd13: ygs = 6'd25;
      4'd14: ygs = 6'd9;
      4'd15: ygs = 6'd0;
      default: ygs = '0;
    endcase
  end
  logic [2:0]  jq;
  logic [1:0]  jmode;
  assign jq    = 3'(job_lgn - 4'(LGE));
  assign jmode = (jq > 3'd2) ? 2'd2 : jq[1:0];
  always_comb begin
    case (mode)
      2'd0: npm = 6'd3;
      2'd1: npm = 6'd13;
      2'd2: npm = 6'd48;
      default: npm = '0;
    endcase
  end

  logic        x_take, y_take, start_pass, ro_go, rd_take, a_val, a_cb0, ro_pad;
  logic [VW:0] cnt_n, ro_v;
  logic [ACW-1:0] acw_n;
  logic [31:0] tix;
  logic [HW-1:0] hix;
  assign x_take     = x_valid & x_ready;
  assign y_take     = y_valid & y_ready;
  assign rd_take    = rd_valid & rd_ready;
  assign start_pass = (ms == M_TILE) & sh_full & ~xb_rd;   // one idle cycle between passes (the row memories)
  assign ro_go      = (ms == M_RO) & (occ < CAP[4:0]);
  assign cnt_n      = (rem > 16'(1 << VW)) ? (VW+1)'(1 << VW) : rem[VW:0];
  assign ro_v       = ro_vb + (VW+1)'(rv);
  assign ro_pad     = (ro_v >= cnt);                       // a padding vector: nothing to read out
  assign a_val      = actl[(DL-1)*CW-1];
  assign a_cb0      = actl[(DL-1)*CW-2];
  assign acw_n[KW-1:0] = actl[(DL-2)*CW +: KW];
  for (genvar g = 0; g < 9; g++) begin : g_dec
    assign acw_n[KW + 5*g]            = a_val & ptt[5*g];
    assign acw_n[KW + 5*g + 1]        = ptt[5*g + 1];
    assign acw_n[KW + 5*g + 2]        = a_cb0 & ptt[5*g + 2];
    assign acw_n[KW + 5*g + 3 +: 2] = ptt[5*g + 3 +: 2];
  end
  assign tix = (((32'(pseg) << lgh) + 32'(lr)) << lgh) + 32'(lc);
  if (LGUB == 0) begin : g_h1
    assign hix = '0;
  end else begin : g_hn
    assign hix = li[LGUB-1:0];
  end

  always_ff @(posedge clk) begin
    // the accumulate control's delay line and the read-out pipeline
    actl    <= {actl[(DL-2)*CW-1:0], ((ms == M_RUN) | start_pass), (cc == '0), pp, (start_pass ? KW'(0) : rv[KW-1:0])};
    acw     <= acw_n;
    t_valid <= {t_valid[6-2:0], r_rd};
    t_tag   <= {t_tag[(6-1)*21-1:0], r_tag};
    if (rd_take) wbeat <= rd_data;

    if (rst) begin
      ms        <= M_IDLE;
      job_ready <= 1'b0;
      x_ready   <= 1'b0;
      swap      <= 1'b0;
      xb_rd     <= 1'b0;
      r_rd      <= 1'b0;
      t_valid   <= '0;
      occ       <= 5'd0;
      ls        <= L_IDLE;
      rq_valid  <= 1'b0;
      rd_ready  <= 1'b0;
      ld        <= '0;
      ld_hi     <= '0;
      tiles     <= 13'd0;
      sh_full   <= 1'b0;
      wave      <= 16'd0;
      rq_addr   <= 32'd0;
      rq_len    <= 24'd0;
    end else begin
      swap  <= 1'b0;
      xb_rd <= 1'b0;
      r_rd  <= 1'b0;
      occ   <= occ + {4'd0, (ro_go & ~ro_pad)} - {4'd0, y_take};
      if (wave != 16'd0) wave <= wave - 16'd1;

      case (ms)
        M_IDLE: begin
          if (job_valid & job_ready) begin
            job_ready <= 1'b0;
            mode  <= jmode;
            lgh   <= jq - 3'(jmode);
            hbm   <= CBW'((6'd1 << (jq - 3'(jmode))) - 6'd1);
            nbm   <= 5'((6'd1 << jq) - 6'd1);
            nrm   <= 2'((3'd1 << jmode) - 3'd1);
            rem   <= job_batch;
            vbase <= 16'd0;
            mul   <= job_mul;
            shift <= job_shift;
            zp    <= job_zp;
            lo    <= job_lo;
            hi    <= job_hi;
            ms    <= M_CHUNK;
          end else
            job_ready <= 1'b1;
        end
        M_CHUNK: begin                               // the next chunk of the job: at most 8 E vectors
          cnt   <= cnt_n;
          part  <= (KW+1)'((cnt_n + (VW+1)'(4 - 1)) >> 2);
          tiles <= 13'(((13'(npm) + 13'd1) << lgh) << lgh);
          lp    <= '0;
          lr    <= '0;
          lc    <= '0;
          iv    <= '0;
          ik    <= '0;
          ica   <= '0;
          ia    <= '0;
          ic    <= 5'd0;
          icb   <= '0;
          x_ready <= 1'b1;
          ms    <= M_INGEST;
        end
        M_INGEST: begin
          if (x_take) begin
            if (ic == nbm) begin
              ic  <= 5'd0;
              icb <= '0;
              ia  <= '0;
              iv  <= iv + 1'b1;
              if ((KW+1)'(ik) + 1'b1 == part) begin
                ik  <= '0;
                ica <= ica + 1'b1;
              end else
                ik <= ik + 1'b1;
              if (iv + 1'b1 == cnt) begin
                x_ready <= 1'b0;
                ms <= M_TILE;
                rr <= '0;
                cc <= '0;
                pp <= '0;
              end
            end else begin
              ic <= ic + 5'd1;
              if (icb == hbm) begin
                icb <= '0;
                ia  <= ia + 1'b1;
              end else
                icb <= icb + 1'b1;
            end
          end
        end
        M_TILE: begin
          if (start_pass) begin                      // the tile is in the shadow registers: start its pass
            swap    <= 1'b1;
            sh_full <= 1'b0;
            wave    <= 16'(E - 1);
            xb_rd   <= 1'b1;
            xb_ra   <= {KW'(0), cc};
            xb_pid  <= pp;
            rv      <= (KW+1)'(1);
            dcnt    <= 16'(DRAIN);
            if (part == (KW+1)'(1)) begin
if (cc == hbm) begin
  cc <= '0;
  if (pp == npm) begin
    pp <= '0;
    ms <= M_DRAIN;
  end else begin
    pp <= pp + 1'b1;
    ms <= M_TILE;
  end
end else begin
  cc <= cc + 1'b1;
  ms <= M_TILE;
end
            end else
              ms <= M_RUN;
          end
        end
        M_RUN: begin
          xb_rd <= 1'b1;
          xb_ra <= {rv[KW-1:0], cc};
          rv    <= rv + 1'b1;
          dcnt  <= 16'(DRAIN);
          if (rv + 1'b1 == part) begin
if (cc == hbm) begin
  cc <= '0;
  if (pp == npm) begin
    pp <= '0;
    ms <= M_DRAIN;
  end else begin
    pp <= pp + 1'b1;
    ms <= M_TILE;
  end
end else begin
  cc <= cc + 1'b1;
  ms <= M_TILE;
end
          end
        end
        M_DRAIN: begin                               // the block's last sums are on their way to the row memories
          dcnt   <= dcnt - 16'd1;
          rv     <= '0;
          ro_rho <= '0;
          ro_ch  <= '0;
          ro_vb  <= '0;
          if (dcnt == 16'd0) ms <= M_RO;
        end
        M_RO: begin
          if (ro_go) begin
            r_rd  <= ~ro_pad;
            r_g   <= ygs[2 +: 4];
            r_sub <= ygs[2-1:0];
            r_v   <= rv[KW-1:0];
            r_tag <= {vbase + 16'(ro_v), (5'(ro_rho) << lgh) | 5'(rr)};
            if (rv + 1'b1 == part) begin
              rv <= '0;
              if (ro_ch == 2'd3) begin
                ro_ch <= '0;
                ro_vb <= '0;
                if (ro_rho == nrm) begin
                  if (rr == hbm) ms <= M_FLUSH;
                  else begin
                    rr <= rr + 1'b1;
                    ms <= M_TILE;
                  end
                end else
                  ro_rho <= ro_rho + 1'b1;
              end else begin
                ro_ch <= ro_ch + 1'b1;
                ro_vb <= ro_vb + (VW+1)'(part);
              end
            end else
              rv <= rv + 1'b1;
          end
        end
        M_FLUSH: begin                               // the chunk's last results leave the output stage
          if (~r_rd & (t_valid == '0)) begin
            vbase <= vbase + 16'(cnt);
            rem   <= rem - 16'(cnt);
            if (rem == 16'(cnt)) begin
              ms <= M_IDLE;
              job_ready <= 1'b1;
            end else
              ms <= M_CHUNK;
          end
        end
        default: ms <= M_IDLE;
      endcase

      // the weight loader: one burst per tile into the shadow registers, one tile ahead of the array
      ld    <= '0;
      ld_hi <= '0;
      case (ls)
        L_IDLE: begin
          if ((tiles != 13'd0) & ~sh_full & ~start_pass & (ms != M_IDLE) & (ms != M_CHUNK)) begin
            rq_valid <= 1'b1;
            rq_addr  <= (tix << LGE) + (tix << LGUB);
            rq_len   <= 24'(TBEATS);
            ls       <= L_REQ;
          end
        end
        L_REQ: begin
          if (rq_valid & rq_ready) begin
            rq_valid <= 1'b0;
            ls       <= L_RX;
            li       <= '0;
            tiles    <= tiles - 13'd1;
            if (lc == hbm) begin
              lc <= '0;
              if (lp == npm) begin
                lp <= '0;
                lr <= lr + 1'b1;
              end else
                lp <= lp + 1'b1;
            end else
              lc <= lc + 1'b1;
          end
        end
        L_RX: begin
          // a beat may land in the shadow registers only when the last swap has passed (wave = 0)
          rd_ready <= (wave <= 16'd1) & ~(rd_take & (li == (LGE+1)'(TBEATS - 1)));
          if (rd_take) begin
            if (~li[LGE]) ld[li[LGE-1:0]] <= 1'b1;
            else          ld_hi[hix] <= 1'b1;
            li <= li + 1'b1;
            if (li == (LGE+1)'(TBEATS - 1)) begin
              sh_full <= 1'b1;
              ls      <= L_IDLE;
            end
          end
        end
        default: ls <= L_IDLE;
      endcase
    end
  end
endmodule

// The activation buffer: one bank per activation block (row part, column part), so that the up to 4 blocks of
// an operand are read in one cycle. A bank holds 2 E vectors of up to 32 / 4 beats, in 64-bit blocks.
// `q` is every bank's output; `qpid` (the product) and `qsb` (the sub-bank) say which words were read.
module gemm_xbuf #(parameter int LGE = 2) (
  input  logic                   clk,
  input  logic                   we_v, we_r,
  input  logic [4-1:0]        wblk,
  input  logic [LGE+4-1:0]   waddr,
  input  logic [16*(1<<LGE)-1:0] wdata,
  input  logic                   rd,
  input  logic [1:0]             rmode,
  input  logic [6-1:0]      rpid,
  input  logic [LGE+4-1:0]   raddr,
  output logic [(16<<LGE)*(16<<((LGE+4>10)?LGE+4-10:0))-1:0] q,
  output logic [6-1:0]      qpid,
  output logic [((LGE+4>10)?LGE+4-10:0):0] qsb
);
  localparam int MEMW = 16 << LGE;
  localparam int AW = LGE + 4;
  localparam int LGS = (AW > 10) ? AW - 10 : 0;       // log2 of the 1024-word sub-banks of a bank
  logic            we;
  logic [LGS:0]    wsb, rsb;
  logic [24-1:0] ptx;                             // the operand of product rpid: per term {use, negate, block}
  assign we = we_v & we_r;
  always_comb begin
    case ({rmode, rpid})
      8'd0: ptx = 24'h20;
      8'd1: ptx = 24'h21;
      8'd2: ptx = 24'h22;
      8'd3: ptx = 24'h23;
      8'd64: ptx = 24'h960;
      8'd65: ptx = 24'h20;
      8'd66: ptx = 24'hd61;
      8'd67: ptx = 24'hc24;
      8'd68: ptx = 24'h25;
      8'd69: ptx = 24'h860;
      8'd70: ptx = 24'h964;
      8'd71: ptx = 24'h9e2;
      8'd72: ptx = 24'h22;
      8'd73: ptx = 24'hde3;
      8'd74: ptx = 24'hca6;
      8'd75: ptx = 24'h27;
      8'd76: ptx = 24'h8e2;
      8'd77: ptx = 24'h9e6;
      8'd128: ptx = 24'hbea960;
      8'd129: ptx = 24'haa0;
      8'd130: ptx = 24'hfebd61;
      8'd131: ptx = 24'heaec24;
      8'd132: ptx = 24'hbe5;
      8'd133: ptx = 24'haea860;
      8'd134: ptx = 24'hbee964;
      8'd135: ptx = 24'h960;
      8'd136: ptx = 24'h20;
      8'd137: ptx = 24'hd61;
      8'd138: ptx = 24'hc24;
      8'd139: ptx = 24'h25;
      8'd140: ptx = 24'h860;
      8'd141: ptx = 24'h964;
      8'd142: ptx = 24'hffa9e2;
      8'd143: ptx = 24'hea2;
      8'd144: ptx = 24'hbfbde3;
      8'd145: ptx = 24'habeca6;
      8'd146: ptx = 24'hfe7;
      8'd147: ptx = 24'hefa8e2;
      8'd148: ptx = 24'hffe9e6;
      8'd149: ptx = 24'hd70b68;
      8'd150: ptx = 24'hc28;
      8'd151: ptx = 24'h971f69;
      8'd152: ptx = 24'h834e2c;
      8'd153: ptx = 24'hd6d;
      8'd154: ptx = 24'hc70a68;
      8'd155: ptx = 24'hd74b6c;
      8'd156: ptx = 24'hbea;
      8'd157: ptx = 24'h2a;
      8'd158: ptx = 24'hfeb;
      8'd159: ptx = 24'heae;
      8'd160: ptx = 24'h2f;
      8'd161: ptx = 24'haea;
      8'd162: ptx = 24'hbee;
      8'd163: ptx = 24'h9e2960;
      8'd164: ptx = 24'h8a0;
      8'd165: ptx = 24'hde3d61;
      8'd166: ptx = 24'hca6c24;
      8'd167: ptx = 24'h9e5;
      8'd168: ptx = 24'h8e2860;
      8'd169: ptx = 24'h9e6964;
      8'd170: ptx = 24'hbeab68;
      8'd171: ptx = 24'haa8;
      8'd172: ptx = 24'hfebf69;
      8'd173: ptx = 24'heaee2c;
      8'd174: ptx = 24'hbed;
      8'd175: ptx = 24'haeaa68;
      8'd176: ptx = 24'hbeeb6c;
      default: ptx = '0;
    endcase
  end
  if (LGS == 0) begin : g_one
    assign wsb = '0;
    assign rsb = '0;
  end else begin : g_many
    assign wsb = {1'b0, waddr[AW-1:10]};
    assign rsb = {1'b0, raddr[AW-1:10]};
  end
  for (genvar b = 0; b < 16; b++) begin : g_bank
    logic hit;
    assign hit = (ptx[5] & (ptx[0 +: 4] == b)) | (ptx[11] & (ptx[6 +: 4] == b)) | (ptx[17] & (ptx[12 +: 4] == b)) | (ptx[23] & (ptx[18 +: 4] == b));
    for (genvar sb = 0; sb < (1 << LGS); sb++) begin : g_sub
      logic bw, br;
      assign bw = we & (wblk == b) & (wsb == sb);
      assign br = rd & hit & (rsb == sb) & ~bw;
      for (genvar k = 0; k < MEMW / 64; k++) begin : g_blk
        if (AW <= 8) begin : g_256
          srambank_64x4x64_6t122 m (.clk(clk), .ADDRESS(bw ? 8'(waddr) : 8'(raddr)), .wd(wdata[64*k +: 64]),
                                    .banksel(bw | br), .read(br), .write(bw),
                                    .dataout(q[MEMW*((b << LGS) + sb) + 64*k +: 64]));
        end else if (AW == 9) begin : g_512
          srambank_128x4x64_6t122 m (.clk(clk), .ADDRESS(bw ? 9'(waddr) : 9'(raddr)), .wd(wdata[64*k +: 64]),
                                     .banksel(bw | br), .read(br), .write(bw),
                                     .dataout(q[MEMW*((b << LGS) + sb) + 64*k +: 64]));
        end else begin : g_1024
          srambank_256x4x64_6t122 m (.clk(clk), .ADDRESS(bw ? 10'(waddr) : 10'(raddr)), .wd(wdata[64*k +: 64]),
                                     .banksel(bw | br), .read(br), .write(bw),
                                     .dataout(q[MEMW*((b << LGS) + sb) + 64*k +: 64]));
        end
      end
    end
  end
  always_ff @(posedge clk)
    if (rd) begin
      qpid <= rpid;
      qsb  <= rsb;
    end
endmodule

// The operand and the input skew: the up to 4 blocks read from the buffer are added with their signs, entry by
// entry (a signed 19-bit operand), and column j of the result (and the swap tag) is delayed j + 1 cycles, so
// that every cell of a row sees its activation one cycle after its left neighbour's sum.
module gemm_skew #(parameter int LGE = 2) (
  input  logic                   clk,
  input  logic                   swap,
  input  logic [(16<<LGE)*(16<<((LGE+4>10)?LGE+4-10:0))-1:0] q,
  input  logic [1:0]             mode,
  input  logic [6-1:0]      qpid,
  input  logic [((LGE+4>10)?LGE+4-10:0):0] qsb,
  output logic [(1<<LGE)-1:0]    swap_o,
  output logic [19*(1<<LGE)-1:0] x_o
);
  localparam int E = 1 << LGE;
  localparam int MEMW = 16 * E;
  localparam int AW = LGE + 4;
  localparam int LGS = (AW > 10) ? AW - 10 : 0;
  logic [4*(2+4)-1:0] ptx;                    // the operand of product qpid: per term {use, negate, block}
  logic [4*4-1:0] qblk;
  logic [4-1:0] quse, qneg;
  always_comb begin
    case ({mode, qpid})
      8'd0: ptx = 24'h20;
      8'd1: ptx = 24'h21;
      8'd2: ptx = 24'h22;
      8'd3: ptx = 24'h23;
      8'd64: ptx = 24'h960;
      8'd65: ptx = 24'h20;
      8'd66: ptx = 24'hd61;
      8'd67: ptx = 24'hc24;
      8'd68: ptx = 24'h25;
      8'd69: ptx = 24'h860;
      8'd70: ptx = 24'h964;
      8'd71: ptx = 24'h9e2;
      8'd72: ptx = 24'h22;
      8'd73: ptx = 24'hde3;
      8'd74: ptx = 24'hca6;
      8'd75: ptx = 24'h27;
      8'd76: ptx = 24'h8e2;
      8'd77: ptx = 24'h9e6;
      8'd128: ptx = 24'hbea960;
      8'd129: ptx = 24'haa0;
      8'd130: ptx = 24'hfebd61;
      8'd131: ptx = 24'heaec24;
      8'd132: ptx = 24'hbe5;
      8'd133: ptx = 24'haea860;
      8'd134: ptx = 24'hbee964;
      8'd135: ptx = 24'h960;
      8'd136: ptx = 24'h20;
      8'd137: ptx = 24'hd61;
      8'd138: ptx = 24'hc24;
      8'd139: ptx = 24'h25;
      8'd140: ptx = 24'h860;
      8'd141: ptx = 24'h964;
      8'd142: ptx = 24'hffa9e2;
      8'd143: ptx = 24'hea2;
      8'd144: ptx = 24'hbfbde3;
      8'd145: ptx = 24'habeca6;
      8'd146: ptx = 24'hfe7;
      8'd147: ptx = 24'hefa8e2;
      8'd148: ptx = 24'hffe9e6;
      8'd149: ptx = 24'hd70b68;
      8'd150: ptx = 24'hc28;
      8'd151: ptx = 24'h971f69;
      8'd152: ptx = 24'h834e2c;
      8'd153: ptx = 24'hd6d;
      8'd154: ptx = 24'hc70a68;
      8'd155: ptx = 24'hd74b6c;
      8'd156: ptx = 24'hbea;
      8'd157: ptx = 24'h2a;
      8'd158: ptx = 24'hfeb;
      8'd159: ptx = 24'heae;
      8'd160: ptx = 24'h2f;
      8'd161: ptx = 24'haea;
      8'd162: ptx = 24'hbee;
      8'd163: ptx = 24'h9e2960;
      8'd164: ptx = 24'h8a0;
      8'd165: ptx = 24'hde3d61;
      8'd166: ptx = 24'hca6c24;
      8'd167: ptx = 24'h9e5;
      8'd168: ptx = 24'h8e2860;
      8'd169: ptx = 24'h9e6964;
      8'd170: ptx = 24'hbeab68;
      8'd171: ptx = 24'haa8;
      8'd172: ptx = 24'hfebf69;
      8'd173: ptx = 24'heaee2c;
      8'd174: ptx = 24'hbed;
      8'd175: ptx = 24'haeaa68;
      8'd176: ptx = 24'hbeeb6c;
      default: ptx = '0;
    endcase
  end
  for (genvar t = 0; t < 4; t++) begin : g_op
    assign qblk[4*t +: 4] = ptx[(2+4)*t +: 4];
    assign qneg[t] = ptx[(2+4)*t + 4];
    assign quse[t] = ptx[(2+4)*t + 4 + 1];
  end
  logic [MEMW*16-1:0] w;                          // per bank: the word of the sub-bank that was read
  for (genvar b = 0; b < 16; b++) begin : g_b
    if (LGS == 0) begin : g_1
      assign w[MEMW*b +: MEMW] = q[MEMW*b +: MEMW];
    end else if (LGS == 1) begin : g_2
      assign w[MEMW*b +: MEMW] = qsb[0] ? q[MEMW*(2*b+1) +: MEMW] : q[MEMW*(2*b) +: MEMW];
    end else begin : g_4                             // LGE <= 7: at most four sub-banks
      assign w[MEMW*b +: MEMW] = qsb[1] ? (qsb[0] ? q[MEMW*(4*b+3) +: MEMW] : q[MEMW*(4*b+2) +: MEMW])
                                        : (qsb[0] ? q[MEMW*(4*b+1) +: MEMW] : q[MEMW*(4*b) +: MEMW]);
    end
  end
  logic [MEMW*4-1:0] xt;                         // per term: the selected bank's beat, an OR over the banks
  for (genvar t = 0; t < 4; t++) begin : g_term
    assign xt[MEMW*t +: MEMW] = ((qblk[4*t +: 4] == 4'd0) ? w[MEMW*0 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd1) ? w[MEMW*1 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd2) ? w[MEMW*2 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd3) ? w[MEMW*3 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd4) ? w[MEMW*4 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd5) ? w[MEMW*5 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd6) ? w[MEMW*6 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd7) ? w[MEMW*7 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd8) ? w[MEMW*8 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd9) ? w[MEMW*9 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd10) ? w[MEMW*10 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd11) ? w[MEMW*11 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd12) ? w[MEMW*12 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd13) ? w[MEMW*13 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd14) ? w[MEMW*14 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd15) ? w[MEMW*15 +: MEMW] : '0);
  end
  for (genvar j = 0; j < E; j++) begin : g_col
    logic [19*4-1:0] tv;
    for (genvar t = 0; t < 4; t++) begin : g_t
      logic [19-1:0] ex;
      assign ex = {3'd0, xt[MEMW*t + 16*j +: 16]};
      assign tv[19*t +: 19] = quse[t] ? (qneg[t] ? (19'd0 - ex) : ex) : 19'd0;
    end
    logic [19-1:0] sum;
    assign sum = tv[19*0 +: 19] + tv[19*1 +: 19] + tv[19*2 +: 19] + tv[19*3 +: 19];
    logic [20*(j+1)-1:0] d;
    if (j == 0) begin : g_first
      always_ff @(posedge clk) d <= {swap, sum};
    end else begin : g_rest
      always_ff @(posedge clk) d <= {d[20*j-1:0], swap, sum};
    end
    assign swap_o[j]       = d[20*j + 19];
    assign x_o[19*j +: 19] = d[20*j +: 19];
  end
endmodule

// The array: E rows; activations, the swap tag and the accumulate control travel down the rows. A weight beat
// `w_d` is a tile row's low 16 bits (`ld`, one row) or a beat of the tile's upper bits, row-major (`ld_hi`, the
// rows of that beat: each row takes its own slice).
module gemm_array #(parameter int LGE = 2) (
  input  logic                clk,
  input  logic [(1<<LGE)-1:0] ld,
  input  logic [(1<<((LGE+2>5)?LGE+2-5:1))-1:0] ld_hi,
  input  logic [16*(1<<LGE)-1:0] w_d,
  input  logic [(1<<LGE)-1:0] swap,
  input  logic [19*(1<<LGE)-1:0] x,
  input  logic [LGE+1+45-1:0] acw,
  input  logic                r_rd,
  input  logic [4-1:0]     r_g,
  input  logic [2-1:0]     r_sub,
  input  logic [LGE+1-1:0] r_v,
  input  logic [15:0]         mul,
  input  logic [5:0]          shift,
  input  logic [15:0]         zp, lo, hi,
  output logic [16*(1<<LGE)-1:0] y
);
  localparam int E = 1 << LGE;
  localparam int XB = 19 * E;
  localparam int ACW = LGE + 1 + 45;
  localparam int LGR = (LGE < 5 - 2) ? LGE : 5 - 2;     // log2 of the tile rows in one beat of upper bits
  logic [E*(E+1)-1:0]    sw;
  logic [XB*(E+1)-1:0]   xx;
  logic [ACW*(E+1)-1:0]  ac;
  assign sw[E-1:0]   = swap;
  assign xx[XB-1:0]  = x;
  assign ac[ACW-1:0] = acw;
  for (genvar i = 0; i < E; i++) begin : g_row
    gemm_row #(.LGE(LGE)) u (
      .clk(clk), .ld(ld[i]), .ld_hi(ld_hi[i >> LGR]), .w_d(w_d),
      .w_h(w_d[2*E*(i & ((1 << LGR) - 1)) +: 2*E]),
      .swap_in(sw[E*i +: E]), .x_in(xx[XB*i +: XB]), .acw(ac[ACW*i +: ACW]),
      .r_rd(r_rd), .r_g(r_g), .r_sub(r_sub), .r_v(r_v),
      .mul(mul), .shift(shift), .zp(zp), .lo(lo), .hi(hi),
      .swap_out(sw[E*(i+1) +: E]), .x_out(xx[XB*(i+1) +: XB]), .acw_o(ac[ACW*(i+1) +: ACW]),
      .y(y[16*i +: 16]));
  end
endmodule

// One row of the array: E cells, the row's accumulators and its output stage. The accumulators hold the result
// blocks of the row block under work in 9 groups of two memories (even and odd vectors): a product's sum is
// added with its sign into one block of every enabled group, read in one cycle and written in the next, and two
// blocks one product updates are never in one group. The accumulate control `acw` (vector, then per group: enable,
// negate, first, slot) enters from the row above one cycle later per row, as the activations do.
module gemm_row #(parameter int LGE = 2) (
  input  logic                clk,
  input  logic                ld, ld_hi,
  input  logic [16*(1<<LGE)-1:0] w_d,
  input  logic [2*(1<<LGE)-1:0] w_h,
  input  logic [(1<<LGE)-1:0] swap_in,
  input  logic [19*(1<<LGE)-1:0] x_in,
  input  logic [LGE+1+45-1:0] acw,
  input  logic                r_rd,
  input  logic [4-1:0]     r_g,
  input  logic [2-1:0]     r_sub,
  input  logic [LGE+1-1:0] r_v,
  input  logic [15:0]         mul,
  input  logic [5:0]          shift,
  input  logic [15:0]         zp, lo, hi,
  output logic [(1<<LGE)-1:0] swap_out,
  output logic [19*(1<<LGE)-1:0] x_out,
  output logic [LGE+1+45-1:0] acw_o,
  output logic [15:0]         y
);
  localparam int E = 1 << LGE;
  localparam int KW = LGE + 1;
  logic [48*(E+1)-1:0] s;
  assign s[47:0] = 48'd0;
  for (genvar j = 0; j < E; j++) begin : g_cell
    gemm_cell u (.clk(clk), .ld(ld), .ld_hi(ld_hi), .w_d(w_d[16*j +: 16]), .w_h(w_h[2*j +: 2]),
                 .swap_in(swap_in[j]), .x_in(x_in[19*j +: 19]),
                 .s_in(s[48*j +: 48]), .swap_out(swap_out[j]), .x_out(x_out[19*j +: 19]),
                 .s_out(s[48*(j+1) +: 48]));
  end

  logic [47:0] sp, sn;
  logic [48*18-1:0] dd;
  logic [5-1:0] r_sel;
  assign sp = s[48*E +: 48];
  assign sn = 48'd0 - sp;
  begin : g_acc0                                    // group 0: 1 result block(s)
    localparam int AG = LGE + 1 - 1 + 0;    // address bits: slot, vector / 2
    logic        en, en_o, ng_o, fi_o, rdr;
    logic [2-1:0] sub, sub_o;
    logic [47:0] d0, d1, wd;
    logic        rd0, rd1, wr0, wr1;
    logic [9:0]  a_w, a_a, a_r, ad0, ad1;
    assign en    = acw[KW + 5*0];
    assign sub   = acw[KW + 5*0 + 3 +: 2];
    assign en_o  = acw_o[KW + 5*0];
    assign ng_o  = acw_o[KW + 5*0 + 1];
    assign fi_o  = acw_o[KW + 5*0 + 2];
    assign sub_o = acw_o[KW + 5*0 + 3 +: 2];
    assign rdr   = r_rd & (r_g == 4'd0);
    assign a_w   = 10'({sub_o, acw_o[KW-1:0]} >> 1);
    assign a_a   = 10'({sub, acw[KW-1:0]} >> 1);
    assign a_r   = 10'({r_sub, r_v} >> 1);
    assign wr0   = en_o & ~acw_o[0];
    assign wr1   = en_o &  acw_o[0];
    assign rd0   = (en & ~acw[0]) | (rdr & ~r_v[0]);
    assign rd1   = (en &  acw[0]) | (rdr &  r_v[0]);
    assign ad0   = wr0 ? a_w : en ? a_a : a_r;
    assign ad1   = wr1 ? a_w : en ? a_a : a_r;
    assign wd    = (fi_o ? 48'd0 : (acw_o[0] ? d1 : d0)) + (ng_o ? sn : sp);
