      srambank_256x4x48_6t122 m1 (.clk(clk), .ADDRESS(ad1), .wd(wd), .banksel(rd1 | wr1), .read(rd1 & ~wr1),
                                  .write(wr1), .dataout(d1));
    end
    assign dd[48*(2*7) +: 48]   = d0;
    assign dd[48*(2*7+1) +: 48] = d1;
  end

  begin : g_acc8                                    // group 8: 4 result block(s)
    localparam int AG = LGE + 1 - 1 + 2;    // address bits: slot, vector / 2
    logic        en, en_o, ng_o, fi_o, rdr;
    logic [2-1:0] sub, sub_o;
    logic [47:0] d0, d1, wd;
    logic        rd0, rd1, wr0, wr1;
    logic [9:0]  a_w, a_a, a_r, ad0, ad1;
    assign en    = acw[KW + 5*8];
    assign sub   = acw[KW + 5*8 + 3 +: 2];
    assign en_o  = acw_o[KW + 5*8];
    assign ng_o  = acw_o[KW + 5*8 + 1];
    assign fi_o  = acw_o[KW + 5*8 + 2];
    assign sub_o = acw_o[KW + 5*8 + 3 +: 2];
    assign rdr   = r_rd & (r_g == 4'd8);
    assign a_w   = 10'({sub_o, acw_o[KW-1:0]} >> 1);
    assign a_a   = 10'({sub, acw[KW-1:0]} >> 1);
    assign a_r   = 10'({r_sub, r_v} >> 1);
    assign wr0   = en_o & ~acw_o[0];
    assign wr1   = en_o &  acw_o[0];
    assign rd0   = (en & ~acw[0]) | (rdr & ~r_v[0]);
    assign rd1   = (en &  acw[0]) | (rdr &  r_v[0]);
    assign ad0   = wr0 ? a_w : en ? a_a : a_r;
    assign ad1   = wr1 ? a_w : en ? a_a : a_r;
    assign wd    = (fi_o ? 48'd0 : (acw_o[0] ? d1 : d0)) + (ng_o ? sn : sp);
    if (AG <= 8) begin : g_256
      srambank_64x4x48_6t122 m0 (.clk(clk), .ADDRESS(ad0[7:0]), .wd(wd), .banksel(rd0 | wr0), .read(rd0 & ~wr0),
                                 .write(wr0), .dataout(d0));
      srambank_64x4x48_6t122 m1 (.clk(clk), .ADDRESS(ad1[7:0]), .wd(wd), .banksel(rd1 | wr1), .read(rd1 & ~wr1),
                                 .write(wr1), .dataout(d1));
    end else if (AG == 9) begin : g_512
      srambank_128x4x48_6t122 m0 (.clk(clk), .ADDRESS(ad0[8:0]), .wd(wd), .banksel(rd0 | wr0), .read(rd0 & ~wr0),
                                  .write(wr0), .dataout(d0));
      srambank_128x4x48_6t122 m1 (.clk(clk), .ADDRESS(ad1[8:0]), .wd(wd), .banksel(rd1 | wr1), .read(rd1 & ~wr1),
                                  .write(wr1), .dataout(d1));
    end else begin : g_1024
      srambank_256x4x48_6t122 m0 (.clk(clk), .ADDRESS(ad0), .wd(wd), .banksel(rd0 | wr0), .read(rd0 & ~wr0),
                                  .write(wr0), .dataout(d0));
      srambank_256x4x48_6t122 m1 (.clk(clk), .ADDRESS(ad1), .wd(wd), .banksel(rd1 | wr1), .read(rd1 & ~wr1),
                                  .write(wr1), .dataout(d1));
    end
    assign dd[48*(2*8) +: 48]   = d0;
    assign dd[48*(2*8+1) +: 48] = d1;
  end
  always_ff @(posedge clk) begin
    acw_o <= acw;
    if (r_rd) r_sel <= {r_g, r_v[0]};
  end
  gemm_scale sc (.clk(clk), .d(dd), .sel(r_sel), .mul(mul), .shift(shift), .zp(zp), .lo(lo), .hi(hi), .y(y));
endmodule

// One multiply-accumulate cell: signed 18-bit weight (a stored block combination) times signed 19-bit activation
// operand (a block combination formed on chip), exact, accumulated modulo 2^48. The weight is double-buffered: `ld`
// loads the shadow's low 16 bits, `ld_hi` its upper bits, `swap_in` (a tag that travels with the activations, one
// cycle ahead of a pass's first vector) moves it into the active register.
module gemm_cell (
  input  logic        clk,
  input  logic        ld, ld_hi,
  input  logic [15:0] w_d,
  input  logic [2-1:0] w_h,
  input  logic        swap_in,
  input  logic [19-1:0] x_in,
  input  logic [47:0] s_in,
  output logic        swap_out,
  output logic [19-1:0] x_out,
  output logic [47:0] s_out
);
  logic [18-1:0]        w_sh, w_act;
  logic signed [37-1:0] p;
  assign p = $signed(w_act) * $signed(x_in);
  always_ff @(posedge clk) begin
    if (ld)    w_sh[15:0] <= w_d;
    if (ld_hi) w_sh[18-1:16] <= w_h;
    if (swap_in) w_act <= w_sh;
    swap_out <= swap_in;
    x_out    <= x_in;
    s_out    <= s_in + {{11{p[37-1]}}, p};
  end
endmodule

// The output stage on one sum, five register stages, none longer than the cell's multiply-accumulate:
//   1  the sum times M, in two halves (the exact sum fits 44 bits: at most 4096 products below 2^31)
//   2  the product
//   3  the product, doubled, shifted right by s: its low 20 bits, and whether it fits them
//   4  rounded (half up) and the zero point added
//   5  clamped
// floor((p + 2^(s-1)) / 2^s) = ((2p >> s) + 1) >> 1 for every s >= 0 (for s = 0: (2p + 1) >> 1 = p).
module gemm_scale (
  input  logic        clk,
  input  logic [48*18-1:0] d,
  input  logic [5-1:0] sel,
  input  logic [15:0] mul,
  input  logic [5:0]  shift,
  input  logic [15:0] zp, lo, hi,
  output logic [15:0] y
);
  logic signed [43:0] a;
  logic signed [38:0] ph;
  logic        [37:0] pl;
  logic signed [59:0] p;
  logic signed [60:0] q;
  logic signed [19:0] q20;
  logic signed [20:0] r, t;
  logic               fit, neg, fit_t, neg_t;
  logic [47:0] aw;                                  // the selected memory's word, an OR over the memories
  assign aw = ((sel == 5'd0) ? d[48*0 +: 48] : 48'd0)
               | ((sel == 5'd1) ? d[48*1 +: 48] : 48'd0)
               | ((sel == 5'd2) ? d[48*2 +: 48] : 48'd0)
               | ((sel == 5'd3) ? d[48*3 +: 48] : 48'd0)
               | ((sel == 5'd4) ? d[48*4 +: 48] : 48'd0)
               | ((sel == 5'd5) ? d[48*5 +: 48] : 48'd0)
               | ((sel == 5'd6) ? d[48*6 +: 48] : 48'd0)
               | ((sel == 5'd7) ? d[48*7 +: 48] : 48'd0)
               | ((sel == 5'd8) ? d[48*8 +: 48] : 48'd0)
               | ((sel == 5'd9) ? d[48*9 +: 48] : 48'd0)
               | ((sel == 5'd10) ? d[48*10 +: 48] : 48'd0)
               | ((sel == 5'd11) ? d[48*11 +: 48] : 48'd0)
               | ((sel == 5'd12) ? d[48*12 +: 48] : 48'd0)
               | ((sel == 5'd13) ? d[48*13 +: 48] : 48'd0)
               | ((sel == 5'd14) ? d[48*14 +: 48] : 48'd0)
               | ((sel == 5'd15) ? d[48*15 +: 48] : 48'd0)
               | ((sel == 5'd16) ? d[48*16 +: 48] : 48'd0)
               | ((sel == 5'd17) ? d[48*17 +: 48] : 48'd0);
  assign a = aw[43:0];
  assign q = $signed({p, 1'b0}) >>> shift;
  assign r = ($signed({q20[19], q20}) + 21'sd1) >>> 1;
  always_ff @(posedge clk) begin
    ph    <= $signed(a[43:22]) * $signed({1'b0, mul});
    pl    <= a[21:0] * mul;
    p     <= $signed({ph, 22'd0}) + $signed({1'b0, pl});
    q20   <= q[19:0];
    fit   <= (q[60:19] == {42{q[19]}});
    neg   <= q[60];
    t     <= r + $signed({5'd0, zp});
    fit_t <= fit;
    neg_t <= neg;
    if (~fit_t)                         y <= neg_t ? lo : hi;
    else if (t < $signed({5'd0, lo})) y <= lo;
    else if (t > $signed({5'd0, hi})) y <= hi;
    else                                y <= t[15:0];
  end
endmodule

// The result FIFO: 2^LGD entries and an output register.
module gemm_fifo #(parameter int W = 8, parameter int LGD = 3) (
  input  logic         clk, rst,
  input  logic         push,
  input  logic [W-1:0] din,
  input  logic         pop_ready,
  output logic         valid,
  output logic [W-1:0] dout
);
  localparam int D = 1 << LGD;
  logic [W*D-1:0]     mem;
  logic [W*(D+1)-1:0] pick;                           // the entry at the read pointer, as an OR over the entries
  logic [LGD-1:0] wp, rp;
  logic [LGD:0]   cnt;
  logic           take, direct;
  assign take   = ~valid | pop_ready;                 // the output register is free after this cycle
  assign direct = take & (cnt == '0);                 // a pushed beat goes straight to it
  assign pick[W-1:0] = '0;
  for (genvar i = 0; i < D; i++) begin : g_entry
    always_ff @(posedge clk)
      if (push & ~direct & (wp == i)) mem[W*i +: W] <= din;
    assign pick[W*(i+1) +: W] = pick[W*i +: W] | ((rp == i) ? mem[W*i +: W] : '0);
  end
  always_ff @(posedge clk) begin
    if (take) begin
      if (cnt != '0)  dout <= pick[W*D +: W];
      else if (push)  dout <= din;
    end
    if (rst) begin
      valid <= 1'b0;
      wp    <= '0;
      rp    <= '0;
      cnt   <= '0;
    end else begin
      if (take) valid <= (cnt != '0) | push;
      if (push & ~direct) wp <= wp + 1'b1;
      if (take & (cnt != '0)) rp <= rp + 1'b1;
      cnt <= cnt + {{LGD{1'b0}}, (push & ~direct)} - {{LGD{1'b0}}, (take & (cnt != '0))};
    end
  end
endmodule
